function preyOf(S,T,p){
var rng=S.rng;
if(SB.PREY_F&&(p.likes==='f'||(p.likes==='both'&&rng()<0.35))){
var kf=Object.keys(SB.PREY_F).filter(function(k){return SB.PREY_F[k].towns.indexOf(T.id)>=0;});
if(kf.length)return SB.PREY_F[rng.pick(kf)];
}
var km=Object.keys(T.prey).filter(function(k){var q=SB.PREY[k];return q&& !q.holy&& !q.incubus;});
return SB.PREY[rng.pick(km.length?km:['drunk'])];
}
function preyEv(S,T,p,R){
var rng=S.rng,q=preyOf(S,T,p),spot=rng.pick(T.spots);
var v=vars(S,p,R,{t:q.name,spot:spot,style:p.style.label});
var sa=p.stats.charm*10+p.stats.tech*6+(p.tr.warmth||0)*8+rng()*40+(q.weak===p.top?15:0)+(p.m.mood-60)/5;
var sr=R.power+rng()*40,d=sa-sr;
var band=6+(p.tr.warmth||0)*8;
var kind=d>band?'win':d< -band?'lose':'truce',ml=0,lost=0,t,why;
t=ST.fmt(pkF(S,R.met?IN_AGAIN:IN_FIRST),v)+ST.fmt(pkF(S,CONTEST),v);
if(kind==='win'){
ml=Math.round(q.vit*(0.6+rng()*0.5)*(1+p.stats.tech*0.05));
p.m.ml+=ml;p.m.mood+=8;p.cnt.rvW=(p.cnt.rvW||0)+1;
if(!p.best||ml>p.best.ml)p.best={name:q.name,ml:ml};
t+=ST.fmt(pkF(S,P_WIN),Object.assign(v,{ml:ml}));
why='取り合いに勝った（誘惑の出来 '+Math.round(sa)+'・相手 '+Math.round(sr)+'）／+'+ml+'ml';
}else if(kind==='lose'){
lost=Math.min(Math.floor(p.m.ml),Math.round(8+rng()*14));
p.m.ml-=lost;p.m.mood-=10;p.cnt.rvL=(p.cnt.rvL||0)+1;
t+=ST.fmt(pkF(S,lost>=3?P_LOSE:P_LOSE0),Object.assign(v,{lost:lost}));
why='取り合いに負けた（誘惑の出来 '+Math.round(sa)+'・相手 '+Math.round(sr)+'）'+(lost?'／-'+lost+'ml':'');
}else{
ml=Math.round(q.vit*(0.3+rng()*0.25));
p.m.ml+=ml;R.truce=true;p.cnt.rvD=(p.cnt.rvD||0)+1;
t+=ST.fmt(pkF(S,P_TRUCE),Object.assign(v,{ml:ml}));
why='互角だったので休戦（誘惑の出来 '+Math.round(sa)+'・相手 '+Math.round(sr)+'）／+'+ml+'ml';
}
R.met++;
var o=ST.say(S,{actors:[p],tag:{win:'獲物の取り合い（勝ち）',lose:'獲物の取り合い（負け）',truce:'獲物の取り合い（休戦）'}[kind],text:t,why:why,mag:kind==='truce'?20:26});
if(R.met===1)ST.key(S,o,p.name+'が'+R.f+'と出くわした');
}
