function duelEv(S,T,p,R){
var rng=S.rng,spot=rng.pick(T.spots),role=roleOf(S,p),cs=caseOf(p,role);
var v=vars(S,p,R,{spot:spot});
var sa=p.stats.charm*8+p.stats.tech*12+rng()*40+(role==='top'?6:0)-p.m.plea/5;
var sr=R.power+rng()*40,d=sa-sr;
var kind=d>7?'win':d< -7?'lose':'draw',ml=0,lost=0,eo=EO(S),low=S.env.lewd==='low';
var t=ST.fmt(pkF(S,DUEL_IN),v);
t+=low?ST.fmt(pkF(S,DUEL_CUT),v):ST.fmt(pkF(S,eo?DUEL_E[cs]:DUEL[cs]),v);
if(kind==='win'){
ml=Math.round(30+rng()*30+p.stats.tech*4);
p.m.ml+=ml;p.m.mood+=10;p.cnt.rvW=(p.cnt.rvW||0)+1;
if(!p.best||ml>p.best.ml)p.best={name:R.name,ml:ml};
t+=ST.fmt(pkF(S,eo?D_WIN_E:D_WIN),Object.assign(v,{ml:ml}));
}else if(kind==='lose'){
lost=Math.min(Math.floor(p.m.ml),Math.round(15+rng()*20));
p.m.ml-=lost;p.m.mana=clamp(p.m.mana-15,0,100);p.m.mood-=12;p.cnt.rvL=(p.cnt.rvL||0)+1;
t+=ST.fmt(pkF(S,eo?D_LOSE_E:D_LOSE),Object.assign(v,{lost:lost}));
}else{
ml=Math.round(6+rng()*10);
p.m.ml+=ml;p.cnt.rvD=(p.cnt.rvD||0)+1;R.truce=true;
t+=ST.fmt(pkF(S,eo?D_DRAW_E:D_DRAW),Object.assign(v,{ml:ml}));
}
t+=ST.fmt(voice(S,DV[kind],p),v);
var who=role==='top'||kind==='win'?dom(p):p;
t=moans(S,t,{m:who});
p.m.plea=clamp(p.m.plea+(kind==='lose'?40:20),0,100);
R.met++;
var why='吸い合い勝負（'+p.name+'の腕 '+Math.round(sa)+'・'+R.name+' '+Math.round(sr)+'）／'+(role==='top'?p.name+'が上（'+(HK.Pos&&HK.Pos.hardTopNpc(p)?'攻めの指定':'気質')+'）':R.name+'が上')+(kind==='win'?'／+'+ml+'ml':kind==='lose'?'／-'+lost+'ml':'／+'+ml+'ml');
var o=ST.say(S,{actors:[p],tag:{win:'吸い合い勝負（勝ち）',lose:'吸い合い勝負（負け）',draw:'吸い合い勝負（引き分け）'}[kind],text:t,why:why,mag:34,kind:'climax'});
if((p.cnt.rvDuel=(p.cnt.rvDuel||0)+1)===1)ST.key(S,o,p.name+'と'+R.name+'の吸い合い勝負');
}
SB.rivalTurn=function(S,T,p,H,sen,h,last){
var R=rv(S);
if(!R||h===0||p.out)return false;
if((p.cnt.rv||0)>=(R.many?4:2))return false;
if(S.rng()>=(R.many?0.2:0.06)*(GOOD_TOWN[T.id]||1))return false;
p.cnt.rv=(p.cnt.rv||0)+1;
if(sexMob(S,p)&&S.rng()<0.45)duelEv(S,T,p,R);
else preyEv(S,T,p,R);
return true;
};
